import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'health_metrics_service.dart';
class HealthTrackingService{static final _db=FirebaseFirestore.instance;static final _auth=FirebaseAuth.instance;static Future<List<Map<String,dynamic>>> history(String key,{int days=30})async{final u=_auth.currentUser;if(u==null)return[];try{final s=await _db.collection('users').doc(u.uid).collection('vital_history').where('key',isEqualTo:key).orderBy('timestamp',descending:true).limit(days*24).get();return s.docs.map((d)=>{...d.data(),'id':d.id}).toList();}catch(_){return[];}}static Future<Map<String,double>> stats(String key,{int days=30})async{final rows=await history(key,days:days);final n=rows.map((e)=>e['value']).whereType<num>().map((e)=>e.toDouble()).toList();if(n.isEmpty)return{'min':0,'max':0,'avg':0,'count':0};return{'min':n.reduce((a,b)=>a<b?a:b),'max':n.reduce((a,b)=>a>b?a:b),'avg':n.reduce((a,b)=>a+b)/n.length,'count':n.length.toDouble()};}static Future<void> save(Map<String,dynamic> values)=>HealthMetricsService.update(values);}